begin;
set local statement_timeout='30s';
create temporary table integration_results(label text);grant select,insert on integration_results to authenticated,service_role;
do $$declare u uuid;w uuid;w2 uuid;h text:=repeat('a',64);secret_hash text:=repeat('b',64);i uuid;k uuid;r jsonb;replayed jsonb;
begin
 select id into u from auth.users order by created_at limit 1;if u is null then raise exception 'Need an Auth account';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 w:=public.create_workspace('Integration fixture — rollback');w2:=public.create_workspace('Other fixture — rollback');
 execute 'set local role authenticated';
 perform public.integration_oauth_begin(w,'gmail',h);
 if public.integration_oauth_consume(w2,'gmail',h) or public.integration_oauth_consume(w,'outlook',h) then raise exception 'OAuth context escaped';end if;
 if not public.integration_oauth_consume(w,'gmail',h) or public.integration_oauth_consume(w,'gmail',h) then raise exception 'OAuth replay';end if;
 i:=public.integration_save(w,'gmail','fixture@example.invalid','encrypted fixture',array['scope'],h);
 if public.integration_get(w2,'gmail') is not null or public.integration_get(w,'google-calendar') is not null then raise exception 'Token context escaped';end if;
 if not public.integration_refresh_claim(w,'gmail',1) or public.integration_refresh_claim(w,'gmail',1) then raise exception 'Concurrent renewal accepted';end if;
 if public.integration_refresh_finish(w,'gmail',2,'new fixture',array['scope']) then raise exception 'Stale token update';end if;
 perform public.integration_disconnect(w,'gmail');
 if public.integration_refresh_finish(w,'gmail',1,'new fixture',array['scope']) or public.integration_get(w,'gmail') is not null then raise exception 'Disconnected connector resurrected';end if;
 perform public.integration_oauth_begin(w,'gmail',h);perform public.integration_oauth_consume(w,'gmail',h);perform public.integration_disconnect(w,'gmail');
 begin perform public.integration_save(w,'gmail','fixture@example.invalid','late fixture',array['scope'],h);raise exception 'Cancelled OAuth saved';exception when insufficient_privilege then null;end;
 insert into integration_results values('OAuth context, single use, refresh lock/version and cancellation');
 k:=public.zapier_key_create(w,'Fixture','test',secret_hash,array['records:read','records:write','tasks:read','tasks:write']);
 begin perform public.zapier_request(secret_hash,'verify','people');raise exception 'Authenticated called privileged gateway';exception when insufficient_privilege then null;end;
 insert into integration_results values('Privileged Zapier gateway inaccessible to authenticated');
 execute 'set local role service_role';
 begin perform public.zapier_request(repeat('c',64),'verify','people');raise exception 'Unknown key accepted';exception when invalid_authorization_specification then null;end;
 r:=public.zapier_request(secret_hash,'create','people','{"display_name":"Zap fixture","email":"fixture@example.invalid"}',0,'event-1');
 replayed:=public.zapier_request(secret_hash,'create','people','{"display_name":"Zap fixture","email":"fixture@example.invalid"}',0,'event-1');
 if r<>replayed then raise exception 'Retry duplicated';end if;
 begin perform public.zapier_request(secret_hash,'create','people','{"display_name":"Changed payload"}',0,'event-1');raise exception 'Idempotency reused';exception when serialization_failure then null;end;
 r:=public.zapier_request(secret_hash,'list','people');
 if jsonb_array_length(r)<>1 or r->0->>'display_name'<>'Zap fixture' or r->0 ? 'attributes' then raise exception 'List isolation failed';end if;
 insert into integration_results values('Zapier authentication, workspace scope, payload bounds and idempotency');
 execute 'reset role';
 update public.zapier_keys set scopes=array['records:read'] where id=k;
 execute 'set local role service_role';
 begin perform public.zapier_request(secret_hash,'create','tasks','{"title":"Denied"}',0,'event-2');raise exception 'Scope escaped';exception when insufficient_privilege then null;end;
 execute 'reset role';
 update relay_private.zapier_credentials set request_count=60,window_started_at=now() where key_id=k;
 execute 'set local role service_role';
 r:=public.zapier_request(secret_hash,'verify','people');if r->>'error'<>'rate_limit' then raise exception 'Rate limit ignored';end if;
 execute 'reset role';update relay_private.zapier_credentials set request_count=0 where key_id=k;
 update public.memberships set role='viewer' where workspace_id=w and user_id=u;
 execute 'set local role service_role';
 begin perform public.zapier_request(secret_hash,'verify','people');raise exception 'Removed admin retained key';exception when invalid_authorization_specification then null;end;
 execute 'reset role';update public.memberships set role='owner' where workspace_id=w and user_id=u;
 execute 'set local role authenticated';perform public.zapier_key_revoke(w,k);
 execute 'set local role service_role';
 begin perform public.zapier_request(secret_hash,'verify','people');raise exception 'Revoked key accepted';exception when invalid_authorization_specification then null;end;
 execute 'reset role';update public.zapier_keys set revoked_at=null,expires_at=now()-interval '1 minute' where id=k;
 execute 'set local role service_role';
 begin perform public.zapier_request(secret_hash,'verify','people');raise exception 'Expired key accepted';exception when invalid_authorization_specification then null;end;
 execute 'reset role';insert into integration_results values('Zapier permissions, rate limit, live membership, revocation and expiry');
end $$;
select label,'PASS' as result from integration_results;
rollback;
